#!/usr/bin/env python3
"""Render two source-reviewed bilingual paper studies; no external runtime dependencies."""
import html,json,hashlib
from pathlib import Path
R=Path(__file__).resolve().parents[1]
E=lambda s:html.escape(str(s),quote=True)
claims=[]
def t(z,e,tag='p',attrs=''):
 claims.append((z,e));return f'<{tag} data-zh="{E(z)}" data-en="{E(e)}" {attrs}>{E(z)}</{tag}>'
def p(z,e,level=''):return t(z,e,attrs=f'data-level="{level}"' if level else '')
def f(s,level='mechanism'):return f'<pre class="formula" data-level="{level}"><code>{E(s)}</code></pre>'
def a(url,z,e):return f'<a href="{E(url)}">{t(z,e,"span")}</a>'
def steps(items):return '<ol class="flow">'+''.join(t(z,e,'li') for z,e in items)+'</ol>'
def lab(kind,z,e):return t(z,e,'h3')+t('教学计算 · 二元概率与参数换算，不运行模型训练。','Teaching computation · Binary probabilities and parameter conversions, not model training.','p','class="lab-note"')+f'<div class="lab" data-lab="{kind}"><div class="controls"></div><div class="results" aria-live="polite" aria-atomic="true"></div></div>'
def task(z,e,az,ae):return '<div class="reading-task">'+t(z,e)+ '<details>'+t('展开推理','Show reasoning','summary')+t(az,ae)+'</details></div>'
def section(i,id,z,e,body,source,loc):
 return f'<section id="{id}" aria-labelledby="{id}-title"><span class="section-num">{i:02}</span>'+t(z,e,'h2',f'id="{id}-title"')+body+'<p class="source-note">'+a(source,'原文依据 ↗','Source ↗')+' · '+E(loc)+'</p></section>'
def table(heads,rows):return '<div class="table-scroll"><table><thead><tr>'+''.join(t(z,e,'th','scope="col"') for z,e in heads)+'</tr></thead><tbody>'+''.join('<tr>'+''.join(t(z,e,'td') for z,e in row)+'</tr>' for row in rows)+'</tbody></table></div>'
def make(slug,short,title,lead,version,source,sections,notes,related,pdfname):
 folder=R/'papers'/slug;folder.mkdir(exist_ok=True)
 depth='<div id="depth-control" class="depth-control">'+''.join(f'<button type="button" data-depth="{k}" aria-pressed="{str(k=="intuition").lower()}">'+t(z,e,'span')+'</button>' for k,z,e in [('intuition','直觉','Intuition'),('mechanism','机制','Mechanism'),('research','研究','Research')])+'</div>'
 original_title='Trust Region Masking for Long-Horizon LLM Reinforcement Learning' if slug=='trm' else 'Batch size-invariance for policy optimization'
 hero=t('论文精读 · '+short,'Paper study · '+short,'p','class="eyebrow"')+t(*title,'h1')+t(*lead,'p','class="reading-intro"')+f'<p class="source-note">{E(original_title)}<br>{E(version)}</p><div class="source-links">'+a(source,'阅读原论文 ↗','Read the paper ↗')+a('../../?theme=ai#themes','人工智能与计算','Artificial Intelligence & Computing')+'</div>'
 body=''.join(section(i+1,*s[:4],source,s[4]) for i,s in enumerate(sections))
 body+=section(len(sections)+1,'sources','来源与延伸阅读','Sources and further reading',p('正文区分论文报告、方法推导与教学计算。原图已核对，实验曲线不按像素估读为精确数据；完整版本、疑点及图示记录见来源清单。','This study distinguishes paper reports, derivations, and teaching computations. Original figures were inspected; plotted curves are not converted into precise numbers by eye. See the ledger for versions, caveats, and visual provenance.')+'<div class="source-links">'+a('sources.md','证据记录','Evidence ledger')+''.join(a('../'+s+'/',z,e) for s,z,e in related)+'</div>',source,'Source ledger')
 data={'slug':slug,'short':short,'title':dict(zip(['zh','en'],title)),'sections':[{'id':s[0],'zh':s[1],'en':s[2]} for s in sections]+[{'id':'sources','zh':'来源','en':'Sources'}]}
 doc='<!doctype html><html lang="zh-CN"><head><meta charset="UTF-8"><meta name="robots" content="noindex, nofollow, noarchive"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+E(title[0])+' · Research Atlas</title><meta name="description" content="'+E(lead[0])+'"><link rel="stylesheet" href="../../assets/rl-foundations.css"><link rel="stylesheet" href="../../assets/bibliography.css"><link rel="stylesheet" href="../../assets/paper.css"></head><body class="atlas-paper rl-foundations" data-paper="'+slug+'">'+depth+'<main id="main"><header class="hero">'+hero+'</header>'+body+'<footer>'+a('../../','返回 Research Atlas','Back to Research Atlas')+'</footer></main><script id="page-data" type="application/json">'+json.dumps(data,ensure_ascii=False).replace('<','\\u003c')+'</script><script src="../../assets/bibliography.js"></script><script src="../../assets/paper-metadata.js"></script><script src="../../assets/paper.js"></script><script src="../../assets/rl-foundations-math.js"></script><script src="../../assets/rl-foundations.js"></script></body></html>'
 (folder/'index.html').write_text(doc)
 (folder/'README.md').write_text(f'# {short}\n\n[讲解页 / Explainer](index.html) · [人工智能与计算](../../?theme=ai#themes)\n\n{lead[0]}\n\n{lead[1]}\n\n- Adopted source: [{version}]({source})\n- [Claim and visual ledger](sources.md)\n- Full Chinese / English, Intuition / Mechanism / Research, keyboard-operable deterministic labs.\n- Editorial source: `scripts/build-rl-foundations.py`; regenerate with Python 3.\n- Local runtime: `assets/rl-foundations.js`, numerical functions: `assets/rl-foundations-math.js`.\n- Validation: `reports/rl-foundations-validation.md`.\n')
 sha=hashlib.sha256(Path('/tmp/rl-paper-sources/'+pdfname+'.pdf').read_bytes()).hexdigest() if Path('/tmp/rl-paper-sources/'+pdfname+'.pdf').exists() else 'See committed source ledger'
 # Keep regeneration independent of a temporary source cache.
 old=folder/'sources.md'
 if sha.startswith('See') and old.exists():
  import re
  sha=re.search(r'PDF SHA-256: `([0-9a-f]+)`',old.read_text()).group(1)
 ledger=f'# {short} — evidence ledger\n\n- Adopted version: [{version}]({source}). Checked 2026-11-02.\n- PDF SHA-256: `{sha}`\n- Bibliography evidence: source first page and arXiv submission history; formal conference record where explicitly listed.\n\n## Section-to-source map\n\n'+''.join(f'- **{s[2]}**: {s[4]}.\n' for s in sections)+'\n## Scientific / version notes\n\n'+notes+'\n\n## Visual inventory\n\n- CSS method flow: original teaching paraphrase of the methods, not a training run.\n- Formula blocks: source objectives in explicit teaching notation; gradient coefficients are distinguished from gradients.\n- Interactive token/ratio/scale displays: synthetic calculations from the stated formula; no experimental predictions. Axes, units and denominator are displayed.\n- Evidence tables: source-reported values only; exact locations and conditions are adjacent. Original figures are linked, not republished.\n- Source PDF images inspected locally; browser screenshots and numerical checks recorded in `reports/rl-foundations-validation.md`.\n\n## Bilingual editorial claims\n\n'+''.join(f'- {en}\n' for zh,en in claims if len(en)>90)+'\n## Reading review\n\nPrerequisites and a reproducible reading task are supplied in both languages. Scientific review, editorial review and technical verification are separate. No human rereading study has been performed.\n'
 (folder/'sources.md').write_text(ledger)
 claims.clear()

trm='https://arxiv.org/abs/2512.23075v5'
sec=[]
b=p('语言模型每次给“下一个 token”分配概率；token 是一段文字的编码单位，不一定是一个汉字或单词。一次 rollout 就是按这些概率逐步生成一条回答。强化学习根据回答的奖励，提高好回答的生成倾向。','A language model assigns probabilities to the next token, an encoded text unit that need not equal a word or character. A rollout generates an answer one token at a time. Reinforcement learning uses the answer’s reward to favor useful responses.')
b+=p('但生成回答的引擎与训练模型可能给出不同概率。精度、算子、专家路由或参数滞后都会造成偏移。前面的选择改变后续看到的上下文，因此长回答中的偏移不能只看成互不相关的单步误差。','The rollout engine and training model may assign different probabilities because of precision, kernels, expert routing, or stale parameters. Earlier choices change later contexts, so mismatch in a long answer is not just a collection of independent one-step errors.')
b+=p('TRM 的操作很直接：逐位置比较两个分布，一旦某个位置越过阈值，整条回答在本次更新中的贡献归零。它控制的是“哪些轨迹用于估计更新”，并未把模型本身投影回某个安全区域。','TRM compares distributions at each position and zeroes the entire answer’s contribution if any position exceeds a threshold. It chooses which trajectories contribute to an update; it does not project the model itself back into a safe region.')
b+=p('关键限制：在已采样回答上通过筛选，不等于所有可能上下文都满足理论条件。TRM v5 明确区分这两件事；高通过率也不保证被掩码目标接近原目标。','Key limit: passing checks on sampled answers does not establish the theoretical condition at every possible context. TRM v5 explicitly separates these claims; a high acceptance rate does not ensure that the masked objective approximates the original objective.')
sec.append(('question','为什么长回答更难稳定','Why long answers are harder to stabilize',b,'§§1–2; §4.4, Remark 4.3'))
b=steps([('采样并保存概率：生成回答 y，同时记录采样策略 πroll 的输出。','Sample and retain probabilities: generate answer y and record rollout-policy outputs.'),('同一前缀重新打分：训练策略 πθ 对每个位置的全部候选 token 计算概率。','Rescore the same prefixes: the training policy assigns probabilities to all candidate tokens.'),('先按位置计算 KL，再取有效位置的最大值，与 δ 比较。','Compute KL at each valid position, then compare the maximum with δ.'),('整条序列保留或置零：按原批次 N 条回答归一化，再更新模型。','Keep or zero the entire sequence: normalize by the original batch of N answers, then update.')])
b+=f('ρₜ = πθ(yₜ | cₜ) / πroll(yₜ | cₜ)\nDₜ = Σᵥ πroll(v | cₜ) log[πroll(v | cₜ) / πθ(v | cₜ)]\nMᵢ = 1[maxₜ Dᵢₜ ≤ δ]\nLmasked = (1/N) Σᵢ Mᵢ Aᵢ Σₜ ρᵢₜ\n∇θ Lmasked ≈ (1/N) Σᵢ Mᵢ Aᵢ Σₜ ρᵢₜ ∇θ log πθ(yᵢₜ | cᵢₜ)')
b+=p('cₜ 是提示词和此前生成内容；yₜ 是实际选中的 token；v 遍历整个词表。ρ 的分母必须是实际采样策略。KL 的方向则是 πroll 到 πθ，使用自然对数，单位为 nat；它衡量整个候选分布的变化，不能用某个 token 的概率差替代。','cₜ is the prompt plus preceding output; yₜ is the selected token; v ranges over the vocabulary. The denominator of ρ must be the actual sampling policy. KL runs from πroll to πθ, uses natural logarithms, and is measured in nats. It compares full distributions, not one token’s probability difference.')
b+=p('Aᵢ=Rᵢ−b 是相对基线 b 的奖励优势。Mᵢ 取 0 或 1，反向传播时视为常量；上式表示论文采用的停止梯度更新。N 是原始批次大小，拒绝后不改成“被接受条数”。padding 不是生成位置，必须排除在最大值、求和和长度之外。','Aᵢ=Rᵢ−b is reward advantage relative to baseline b. Mᵢ is binary and treated as constant during backpropagation; the expression describes the paper’s stop-gradient update. N is the original batch size, not the accepted count. Padding is excluded from maxima, sums, and lengths.')
b+=p('标准 PPO 的 min 裁剪依优势正负而变，并不是双侧都硬置零。例如 A<0 且 ρ 很大时，未裁剪分支仍有梯度。TRM 则把同一回答的所有有效位置一起掩码；代价是连同其中较可靠的位置也一起丢弃。','Standard PPO clipping depends on the sign of advantage; it does not zero both sides. For A<0 and large ρ, the unclipped branch still has a gradient. TRM masks all valid positions in the answer together, sacrificing reliable positions along with the outlier.')
b+=p('若无法保存全词表 logits，附录 E 提议：用 k₂(ρ)=½(log ρ)² 检查最大异常，用 k₃(ρ)=ρ−1−log ρ 检查平均偏移。在完整支持条件下，k₃ 对采样分布取期望等于上述 KL；单次样本值不等于精确 KL，k₂ 也不是无偏 KL 估计。','Without stored full-vocabulary logits, Appendix E proposes k₂(ρ)=½(log ρ)² for maximum-outlier detection and k₃(ρ)=ρ−1−log ρ for average drift. Under full support, the expectation of k₃ under the rollout distribution equals this KL. A single sampled value is not exact KL, and k₂ is not an unbiased KL estimator.','mechanism')
sec.append(('method','从 token 检查到序列掩码','From token checks to sequence masks',b,'Eq. (22)–(23); Algorithm 1; §§4.1–4.3; Appendix E'))
b=lab('trm-mask','一处偏移，整条回答会怎样？','How does one outlier affect an answer?')
b+=p('此处每个位置只有两个候选项，采样分布固定为 [0.5, 0.5]，实际选中第一个候选项。第一条回答的训练概率为 [0.52, 0.54, q, 0.48, 0.51, 0.53]；第二条每个位置均为 0.52、优势固定为 −0.5。两条回答同长，原批次 N=2。','Each position has two candidates, rollout probabilities [0.5, 0.5], and the first candidate is selected. The first answer’s training probabilities are [0.52, 0.54, q, 0.48, 0.51, 0.53]. The second uses 0.52 everywhere and advantage −0.5. Both answers have the same valid length; the original batch size is N=2.')
b+=task('试一试：保持 q=0.9、δ=0.05，把有效长度从 6 改成 2。为什么整条序列从拒绝变成接受？','Try q=0.9 and δ=0.05, then change valid length from 6 to 2. Why does rejection become acceptance?','异常发生在第 3 个位置。长度为 2 时它属于 padding，不参与最大值与更新求和。剩余最大 KL 约 0.00321，小于 0.05。不能让 padding 的概率改变有效回答的掩码。','The outlier is at position 3. At length 2 it is padding, excluded from both the maximum and update sum. The remaining maximum KL is about 0.00321, below 0.05. Padding probabilities must not change the answer’s mask.')
sec.append(('lab','观察掩码，而不是猜测','Inspect the mask',b,'Algorithm 1; Eq. (22)–(23); synthetic binary example'))
b=p('论文把真实奖励变化与代理目标之间的差异写成“上下文分布漂移 × 后续更新影响”。KL 链式法则与 Pinsker 不等式给出一种控制上下文漂移的办法，TV 耦合给出另一种；综合多条独立上界可得到更紧的界。','The paper decomposes the gap between reward change and its surrogate into context-distribution shift and the effect of subsequent updates. The KL chain rule and Pinsker’s inequality bound the shift one way; TV coupling bounds it another. Taking the minimum of valid bounds can tighten the result.')
b+=p('TV（总变差距离）是两个离散概率分布逐项差的绝对值之和的一半，范围为 0 到 1。它可以理解为使两个分布一致至少需要重新分配多少概率质量。KL 为 0 表示两个分布一致，但一般没有 1 这个上限。','TV, total variation distance, is half the sum of absolute differences between two discrete probability distributions, ranging from 0 to 1. It measures the probability mass that must be reassigned to make them agree. KL is zero for identical distributions but generally has no upper bound of 1.')
b+=f('L′ = Eroll[R Σₜ(ρₜ − 1)]\n|J(πθ) − J(πroll) − L′| ≤ B\nBclassical = T(T−1)δ\nBPM = 4 min(1, √(δ/2)) Σₜ₌₁ᵀ min(1, √((t−1)δ/2))')
b+=p('J 是期望序列奖励，R∈[0,1]；T 为固定或按约定补齐的理论时域。δ 在这里约束所有可达上下文的最大 KL，不能直接拿一批样本的最大值代替。L′ 是中心化的奖励形式，满足 πθ=πroll 时 L′=0。对于固定 b，未掩码的优势形式 L 与 L′ 相差 T(Jroll−b)，梯度相同而数值未必相同。','J is expected sequence reward with R∈[0,1]; T is the fixed or consistently padded theoretical horizon. Here δ bounds maximum KL over all reachable contexts, not merely one sampled batch. L′ is the centered reward-form surrogate, zero at πθ=πroll. For fixed b, the unmasked advantage form L differs by T(Jroll−b): the gradients agree but the values need not.')
b+=lab('trm-bound','长序列如何放大误差上界？','How does sequence length affect the error bound?')
b+=p('演示计算式 (12) 的带上限精确求和，以及经典 KL 上界；没有模拟奖励，也没有声称这就是全部方法的最小界 B*。即使上界变小，也还要检查 L′ 是否超过它，才能按相应定理判断改进。','The demo evaluates the capped sum in Eq. (12) and the classical KL bound. It does not simulate rewards or compute the full minimum B*. A smaller bound still requires checking whether L′ exceeds it before the relevant theorem certifies improvement.')
b+=p('研究细节：Mixed 界额外利用整条轨迹的 KL 或 TV；Adaptive 界保留各位置期望 TV，并按剩余长度选择较紧的路线。表 1 在 T=4096、δ=10⁻⁴、ε=0.005、序列 KL=0.01、序列 TV=0.05 时，将经典 KL 界约 1677 降至统一界 ≤4.1。这是理论参数代入，不是 AIME 提升幅度。','Research detail: Mixed bounds additionally use trajectory KL or TV. Adaptive bounds retain expected TV by position and choose the tighter route for the remaining horizon. Table 1 uses T=4096, δ=10⁻⁴, ε=0.005, trajectory KL=0.01 and TV=0.05: about 1677 for the classical KL bound versus a unified bound ≤4.1. This is a theoretical parameter calculation, not an AIME improvement.','research')
b+=p('在全局条件成立时，所有轨迹均通过，M≡1，掩码目标才与原目标相同。若拒绝真实发生，附录 G 的无全局条件界改用奖励形式 L′masked，并付出接受区域误差 BA、拒绝率 r 和序列 TV 的代价；它不能直接证明算法的停止梯度优势更新必然改进。','Under the global condition every trajectory passes, M≡1, and the masked and full objectives coincide. If rejection occurs, Appendix G’s precondition-free result uses reward-form L′masked and pays for accepted-region error BA, rejection rate r, and trajectory TV. It does not directly prove monotonic improvement for the algorithm’s stop-gradient advantage update.','research')
sec.append(('theory','理论能保证到哪一步','What the theory can certify',b,'Remark 2.1; Theorems 3.3–3.8; Table 1; Theorem 4.2 & Remark 4.3; Appendix G'))
b=p('实验用 Qwen3-8B-Base，在去重后的 DAPO-MATH-17k 上做 Zero-RL 数学训练：GRPO 组大小 16，批次 32，学习率 10⁻⁶；采样使用 vLLM，训练使用 PyTorch FSDP。AIME25 评测温度 1.0、top-p 0.95，报告 avg@32。','Experiments train Qwen3-8B-Base on deduplicated DAPO-MATH-17k in a Zero-RL setup: GRPO group size 16, batch size 32, learning rate 10⁻⁶, vLLM sampling and PyTorch FSDP training. AIME25 evaluation uses temperature 1.0, top-p 0.95, and avg@32.')
b+=table([('比较','Comparison'),('原图观察','Observation'),('能支持什么','What it supports')],[[('图 1：Token IS / PPO 裁剪 (0.8, 1.28)','Fig. 1: Token IS / PPO clipping (0.8, 1.28)'),('该配置下裁剪曲线出现更高概率偏差、较低 AIME25 分数。','Clipping shows a larger probability gap and lower AIME25 score in this setup.'),('单 token 裁剪并非必然稳定。','Token clipping is not inevitably stabilizing.')],[('图 2：Max δ=0.05 / Avg δ=0.001','Fig. 2: Max δ=0.05 / Avg δ=0.001'),('两种 TRM 曲线比该 PPO 对照更稳定地改善分数。','Both TRM variants improve scores more consistently than this PPO comparator.'),('支持这组阈值的实用性；不证明平均值控制最大值。','Supports these settings; does not prove a mean bounds a maximum.')],[('图 3：Max 0.1 / Avg 0.002 / 二者结合','Fig. 3: Max 0.1 / Avg 0.002 / combined'),('单独放宽时失败，合用表现更稳定。','Looser criteria fail individually; combining them is more stable.'),('最大异常与累计漂移提供互补信息。','Outliers and accumulated drift carry complementary information.')]])
b+=p('纵轴“Log Absolute PPL Gap”按式 (25) 先计算每条回答的平均 log 概率差，再取绝对值并跨回答平均；它不是最大 token KL。三张图未给出多随机种子的误差带，也未提供足够数值表用于精确抄录终点，因此这里只归纳曲线趋势。','The “Log Absolute PPL Gap” in Eq. (25) averages log-probability differences within each answer, takes an absolute value, then averages across answers. It is not maximum token KL. These figures provide no multi-seed error bands or sufficiently detailed numerical tables for exact endpoints, so only their qualitative trends are summarized.')
b+=a('https://arxiv.org/pdf/2512.23075v5#page=10','查看图 1–2（PDF 第 10 页）','Inspect Figures 1–2 (PDF p. 10)')+' · '+a('https://arxiv.org/pdf/2512.23075v5#page=11','查看图 3','Inspect Figure 3')
sec.append(('evidence','实验支持了哪些结论','What the experiments support',b,'§5; Eq. (25); Figures 1–3, PDF pp. 10–11'))
b=p('长度无关的阈值不等于长度无偏。只要每个位置有小概率 p 违规，在独立同分布的教学假设下，通过率就是 (1−p)ᵀ。长推理链有更多触发拒绝的机会，可能被系统性低估。','A length-independent threshold is not length-neutral selection. Under an illustrative i.i.d. per-position violation probability p, acceptance is (1−p)ᵀ. Long reasoning chains have more chances to fail and may be systematically underrepresented.')
b+=p('附录 F 提出加权归一化的 LN-TRM 和平均 |ρ−1| 的 SER 变体；这些改变了筛选准则与保证条件，不应与 Max-TRM 混称，也没有在图 1–3 中给出对应消融。保存完整词表 logits 的存储、传输与计算代价，也不能被“无额外模型推理”一句话抹去。','Appendix F proposes weighted, normalized LN-TRM and SER based on mean |ρ−1|. They change the selection criterion and guarantee conditions, and have no corresponding ablation in Figures 1–3. “No extra model inference” also does not eliminate the storage, transfer, and computation costs of full-vocabulary logits.')
b+=p('与站内 Rollout 校正专题的关系：重要性采样修正概率比，TRM 决定舍弃哪些轨迹，两者解决不同环节。既有专题引用早期 v1；本页依据 v5，特别保留新版对全局前提和掩码目标的限定。','Relation to the Rollout Correction topic: importance sampling changes probability weights; TRM chooses trajectories to discard. They address different parts of the estimator. The existing topic cites early v1; this page adopts v5 and retains its explicit qualifications about global assumptions and masked objectives.')
sec.append(('limits','代价、长度偏差与版本边界','Costs, length bias, and version boundaries',b,'§4.4; Appendix E–G; Figures 1–3'))
make('trm','TRM',('TRM：让长推理链的更新更可靠','TRM: more reliable updates for long reasoning chains'),('一个 token 的分布偏移为何会影响整条回答？从序列掩码、误差上界到数学推理实验，逐层理解 TRM。','Why can one token’s distribution shift affect an entire answer? Study TRM through sequence masks, error bounds, and mathematical-reasoning experiments.'),'arXiv 2512.23075v5 · 2026-06-26',trm,sec,'- Original PDF pp. 1, 6, 8, 10–11 visually inspected: byline, Table 1, Algorithm 1 and Figures 1–3.\n- §4.1 numerical example prints πroll=0.9, πθ=0.001 yet calls their defined ratio about 900. With Eq. (2) direction it is 1/900. This page uses the equation-defined direction, not that reversed numerical example.\n- Value bounds use centered L′ as required by Remark 2.1; uncentered advantage form is not silently substituted.\n- Eq. (12) is evaluated as an exact finite sum; Eq. (14) scaling is not treated as an exact finite-sum identity.\n- v5 Theorem 4.2 requires the global precondition; Remark 4.3 and Appendix G qualify the masked objective. Acceptance on a sampled path does not certify all reachable contexts.\n- Experiments do not identify enough raw values for numerical curve reconstruction; no pixel-derived endpoints or synthetic accuracy curves.\n- TRM first-page author affiliations are mapped only where numbered: Jiacai Liu → Fudan; Jiawei Xu, Ziniu Li, Baoxiang Wang → CUHK Shenzhen. Unmarked authors remain unmapped. Formal publication/acceptance unverified.',[('rollout-correction','Rollout 校正','Rollout correction'),('rollout-correction-math','校正的数学','Correction mathematics'),('batch-size-invariance','批量大小不变性','Batch size-invariance'),('ppo','PPO','PPO')],'trm')

src='https://arxiv.org/abs/2110.00641v3';sec=[]
b=p('批量大小 B 是一次更新使用多少个样本。减小 B 通常能省显存，却会让更新更频繁、梯度更嘈杂。这里“不变性”的意思是：适当调整参数后，消耗同样多环境样本时，学习表现能大致保持接近；不是每一步参数完全相同，也不是运行时间相同。','Batch size B is the number of samples used for an update. Smaller batches can save memory but cause more frequent, noisier updates. Here invariance means approximately comparable learning after the same number of environment samples, with compensating hyperparameter changes. It does not mean identical parameters after each step or equal runtime.')
b+=p('普通 PPO 让同一个旧策略兼任两职：说明数据是怎样采出来的，以及规定新策略不要离谁太远。批量变小会改变这个参照的“年龄”，所以只改学习率仍可能改变优化行为。论文把这两个角色拆开。','Standard PPO gives one old policy two jobs: describe how data were sampled, and provide a recent anchor for limiting updates. Smaller batches change the anchor’s age, so changing the learning rate alone can still alter optimization. This paper separates the roles.')
b+=steps([('行为策略 πbehav：确实生成这批数据，负责重要性采样的分母。','Behavior policy πbehav: actually sampled the data; supplies the importance-weight denominator.'),('近端策略 πprox：近期模型的参数平均，负责限制更新幅度。','Proximal policy πprox: a parameter average of recent models; anchors update size.'),('当前策略 πθ：正在被优化；既与数据来源比较，也与近期参照比较。','Current policy πθ: being optimized; compared separately with the sampler and the recent anchor.')])
b+=p('重要性权重是“目标动作概率 ÷ 采样动作概率”，用来修正抽样偏好。近端的含义是“靠近当前模型的参照”。优势 A 是动作相对基准表现的估计，正值希望增加其概率，负值希望降低。','An importance weight is target action probability divided by sampling probability; it corrects sampling preference. Proximal means a recent anchor near the current model. Advantage A estimates how much better an action is than a baseline: positive favors increasing its probability, negative favors decreasing it.')
sec.append(('question','批量变小，为什么行为也变了','Why changing batch size changes behavior',b,'§§1–3; optimization and iteration batch definitions in §3.3'))
b=f('w = πprox(a|s) / πbehav(a|s)\nr = πθ(a|s) / πprox(a|s)\nLclip = Ebehav[w · min(rA, clip(r, 1−ε, 1+ε)A)]\nLKL = Ebehav[(πθ/πbehav)A − λ KL(πprox ∥ πθ)]')
b+=p('s 是环境状态，a 是采样动作，Ebehav 表示按实际采样数据取平均。ε 是裁剪宽度，λ 是 KL 惩罚强度（原文用 β；这里改写以免与平均衰减率混淆）。行为与近端策略都视为固定，梯度只通过当前策略。','s is the state, a the sampled action, and Ebehav the average over actual sampled data. ε is clip width; λ is the KL penalty strength (β in the paper, renamed here to distinguish it from averaging decay). Behavior and proximal policies are fixed; gradients flow through the current policy.')
b+=p('未裁剪时 w·r=πθ/πbehav，近端策略恰好消去；它只决定裁剪或惩罚发生在哪里。不能把 πprox 当作数据来源来替换重要性采样分母。这个动作层面的修正也不等于已经完全修正任意陈旧数据的状态分布和优势估计。','Without clipping, w·r=πθ/πbehav, so the proximal policy cancels: it only controls where clipping or regularization acts. It cannot replace the behavior policy in the sampling denominator. This action-level correction also does not fully correct arbitrary stale state distributions or advantage estimates.')
b+=lab('batch-ratios','把三个策略分开调节','Adjust the three policies separately')
b+=p('教学例子只跟踪已采样动作的概率：pbehav=0.2、pprox=0.4、pθ=0.6、A=1、ε=0.2。w=2，r=1.5，未裁剪信号为 3；裁剪后为 2×1.2=2.4。将 A 改为负值，观察 min 的另一分支仍可产生更新。','This teaching example tracks the sampled action: pbehav=0.2, pprox=0.4, pθ=0.6, A=1, ε=0.2. Then w=2 and r=1.5; the unclipped signal is 3 and the clipped value is 2×1.2=2.4. Make A negative to inspect the other min branch, which can remain active.')
sec.append(('objective','一个目标中的两个参照','Two references inside one objective',b,'§2, decoupled KL-penalized and clipped objectives; Appendix A'))
b=p('SGD（随机梯度下降）按当前小批样本估计的改进方向更新参数。Adam 还根据过去梯度的平均与大小，自适应地调节各参数的步幅。PPG（分阶段策略梯度）把策略学习与辅助学习分成阶段，因此还需要控制每个阶段使用的样本数。','SGD, stochastic gradient descent, updates parameters using a direction estimated from the current minibatch. Adam also uses averages and magnitudes of past gradients to adapt each parameter’s step. PPG, Phasic Policy Gradient, separates policy learning from auxiliary learning, so samples per phase also matter.')
b+=p('EWMA 是指数加权移动平均：越新的模型参数权重越大，只保存一个平均模型就能概括一段历史。论文平均的是网络参数，不是动作概率。每次策略梯度更新后更新平均；PPG 的辅助阶段结束后，在下一个策略阶段重新初始化平均。','EWMA is an exponentially weighted moving average: recent model parameters get greater weight, and a single averaged model summarizes the history. The paper averages network parameters, not action probabilities. It updates the average after each policy-gradient step; PPG reinitializes it at the start of the next policy phase after auxiliary training.')
b+=f('H = βprox / (1 − βprox)\nBnew = B / c\nHnew = cH                 βprox,new = cH / (1 + cH)\nαSGD,new = α / c          αAdam,new = α / √c\nNπ,new = cNπ             Wadv,new = cWadv')
b+=p('H 是稳态 EWMA 的平均年龄，单位为梯度步；βprox 越接近 1，参照越旧。c 是批量缩小倍数。把每步样本量降为 1/c、把 H 增为 c 倍，H×B 这个按样本数衡量的年龄保持不变。Wadv 是估计优势均值与方差的有效迭代窗口，Nπ 是 PPG 每个阶段的策略迭代数。','H is the steady-state EWMA mean age in gradient steps; βprox near 1 means an older anchor. c is the batch reduction factor. Dividing samples per step by c while multiplying H by c preserves age measured in samples, H×B. Wadv is the effective iteration window for advantage statistics, and Nπ is the number of policy iterations per PPG phase.')
b+=p('为何 Adam 与 SGD 不同？在梯度噪声占主导的小批量区间，Adam 的均方根梯度分母随批量缩小约增大 √c，已经抵消一部分步幅；因此外部步长再除以 √c，而 SGD 使用线性缩放。超出这个条件，规则可能不再保持行为。','Why do Adam and SGD differ? In the noise-dominated small-batch regime, Adam’s RMS-gradient denominator grows by about √c when batches shrink, already reducing part of the effective step. Its external step size is therefore divided by √c, while SGD uses linear scaling. Outside that regime the rules may not preserve behavior.')
b+=lab('batch-scale','用样本数衡量参照的年龄','Measure anchor age in samples')
b+=p('换算以附录 B 的设置为起点：256 个并行环境，每次 rollout 256 步，每个 epoch 分成 8 个 minibatch，因此迭代批次 65,536、优化批次 8,192；α=0.0005，H=8（βprox 精确值 8/9），Nπ=32。这里展示确定性参数换算，不预测训练曲线。','Conversions start from Appendix B: 256 parallel environments, 256 steps per rollout, and 8 minibatches per epoch, giving iteration batch 65,536 and optimization batch 8,192; α=0.0005, H=8 (exact βprox=8/9), Nπ=32. The demo computes parameters deterministically; it does not predict learning curves.')
b+=p('附录 A 对有限历史使用归一化 EWMA：wnew=1+βw，θprox←θ/wnew+βwθprox/wnew；初始化 θprox=θ、w=1。因此 H=β/(1−β) 是稳态年龄，而不是第一步就精确成立。Adam 的 β₁、β₂ 可另取 β₁^(1/c)、β₂^(1/c)，但主实验多未使用这一可选调整。','Appendix A normalizes finite-history EWMA: wnew=1+βw and θprox←θ/wnew+βwθprox/wnew, initialized with θprox=θ and w=1. Thus H=β/(1−β) is a steady-state age, not exact at the first step. Adam’s β₁ and β₂ can additionally become β₁^(1/c) and β₂^(1/c); most main experiments omit this optional adjustment.','research')
sec.append(('scaling','让学习进度按样本数对齐','Align learning progress by sample count',b,'§§3.1–3.3, §4; Appendices A–D; Tables 1, 3–4'))
b=p('主要实验是 16 个 Procgen 游戏的 hard 难度、IMPALA 卷积网络，不是大语言模型。训练通常持续 1 亿环境步；批量不变性使用 PPG-EWMA，策略 epoch 数 Eπ=1。并行环境从 256 依次降至 64、16、4、1，跨度 256 倍。','The main experiments use 16 Procgen games on hard difficulty and an IMPALA convolutional network, not LLMs. Runs usually last 100 million environment steps. Batch-invariance experiments use PPG-EWMA with one policy epoch, Eπ=1. Parallel environments drop from 256 to 64, 16, 4 and 1, spanning a factor of 256.')
b+=table([('证据','Evidence'),('原文报告','Paper report'),('阅读口径','Interpretation')],[[('图 2–3：最大与最小批量','Figs. 2–3: largest vs smallest batch'),('平均归一化回报差 0.052；去掉 Heist 后 0.019。','Mean normalized-return gap 0.052; 0.019 excluding Heist.'),('3 个种子；主结论仍保留 Heist，不把排除值当作全部任务表现。','3 seeds; Heist remains in the main result, not silently excluded.')],[('表 5：移除 Adam 步长调整','Table 5: remove Adam step adjustment'),('Default / 256：差异之差 0.709，Z=6.87。','Default / 256: difference-in-differences 0.709, Z=6.87.'),('这是不变性差距的恶化量，不是模型平均回报。','This is deterioration of the invariance gap, not average return.')],[('表 5：移除优势归一化窗口调整','Table 5: remove advantage-window adjustment'),('Default / 256：0.224，Z=4.47。','Default / 256: 0.224, Z=4.47.'),('优势统计量的样本规模也影响小批量学习。','The sample count used for advantage statistics matters too.')],[('表 5：不调整近端平均年龄','Table 5: do not adjust proximal age'),('Default / 256：0.041，Z=4.80。','Default / 256: 0.041, Z=4.80.'),('效应小于步长调整，但该比较仍显著。','Smaller effect than step scaling, but significant in this comparison.')]])
b+=p('图 2 横轴是环境步数、纵轴是跨游戏平均归一化回报；阴影为 3 个种子的标准差。图 3 用最后 400 万步的表现计算各游戏批量差距，误差棒为标准误，纵轴采用平方根尺度。表 5 的分层非参数检验对 16 次比较作 Bonferroni 校正，阈值为 0.001/16；这些不确定性定义不能互换。','Figure 2 plots environment steps against mean normalized return across games; shading is standard deviation over 3 seeds. Figure 3 compares batch sizes per game using the last 4 million steps, with standard-error bars and a square-root axis. Table 5 uses a stratified nonparametric test with Bonferroni correction for 16 comparisons, threshold 0.001/16. These uncertainty definitions are not interchangeable.')
b+=p('图 1 的陈旧数据实验支持分工：分母保留真实行为策略，同时用近期近端策略约束更新，比把近期策略错当成采样来源更稳定。图 4 的直接比较使用 4 个种子，EWMA 在未用于调参的后 8 个游戏中对 PPO 与 PPG 都有收益，但总体收益较小。','Figure 1’s stale-data experiment supports the division of roles: retaining the true behavior denominator while anchoring updates to a recent policy is more robust than treating that recent policy as the sampler. Figure 4 uses 4 seeds; EWMA benefits both PPO and PPG on all 8 games held out from hyperparameter tuning, but the overall benefit is modest.')
b+=a('https://arxiv.org/pdf/2110.00641v3#page=7','查看图 2–3','Inspect Figures 2–3')+' · '+a('https://arxiv.org/pdf/2110.00641v3#page=19','查看表 5','Inspect Table 5')+' · '+a('https://papers.neurips.cc/paper_files/paper/2022/hash/6ceb6c2150bbf46fd75528a6cd6be793-Abstract-Conference.html','NeurIPS 2022 正式记录','Official NeurIPS 2022 record')
sec.append(('evidence','收益来自哪些调整','Which adjustments explain the results',b,'§§5.1–5.3; Figures 1–4; Appendix B, D, E; Table 5'))
b=p('适用条件不能省略：优化批次需足够小；论文的不变性实验同步改变优化批次与迭代批次，且 Eπ=1。多次重复遍历极小批次会反复利用同一批数据，不能自动套用相同结论。','The conditions matter: optimization batches must be sufficiently small. The invariance experiments scale optimization and iteration batches together and use Eπ=1. Repeated passes over tiny batches reuse the same data; the same conclusion does not automatically apply.')
b+=p('Heist 是明显例外；附录 D 调整 Adam 的 β₁、β₂ 仍未消除差距。PPG 辅助阶段为控制耗时，还保留了每 worker 的 minibatch 大小并采用单独的步长调整。这里没有证明任意任务、任意大批量或 LLM 后训练都满足不变性。','Heist is a clear exception; changing Adam β₁ and β₂ in Appendix D does not remove its gap. To control runtime, the PPG auxiliary phase also keeps minibatch size per worker fixed and uses separate step-size adjustments. The paper does not establish invariance for arbitrary tasks, large batches, or LLM post-training.')
b+=p('平均模型需要额外参数存储和前向计算。原文估计，不含环境执行的计算开销增加约 PPO 30%、PPG 2.3%；其实现的实际运行时间增幅为 19% 和 3%。样本效率与运行效率是两种不同指标。','The averaged model requires additional parameter storage and forward passes. The paper estimates compute overhead excluding environment stepping at 30% for PPO and 2.3% for PPG; measured wall-clock increases in its implementation are 19% and 3%. Sample efficiency and runtime efficiency are different metrics.')
b+=task('假设批量缩小 4 倍：仅把 Adam 步长除以 2、但不改 βprox，会发生什么？','If batch size shrinks 4×, what happens if you only halve Adam’s step size and leave βprox unchanged?','优化器采用了平方根缩放，但参照平均年龄 H 仍是 8 个梯度步。每步样本数变成四分之一，因此样本尺度年龄由 65,536 降为 16,384。把 H 改为 32、βprox 改为 32/33，才能恢复原样本尺度年龄；优势窗口和 PPG 阶段设置仍须一起考虑。','The optimizer follows square-root scaling, but the anchor remains 8 gradient steps old. With a quarter as many samples per step, its sample age falls from 65,536 to 16,384. H=32 and βprox=32/33 restore that age; advantage-statistics windows and PPG phase settings also need consideration.')
b+=p('与 Rollout 校正专题的联系：它为“采样策略”和“近端参照”应分开的设计提供原始论文依据。TRM 则进一步讨论长序列上的分布偏移和拒绝掩码；两篇论文的任务、假设与实验对象不同。','Relation to Rollout Correction: this paper provides original evidence for separating the sampling policy from the proximal anchor. TRM then addresses long-sequence mismatch and rejection masks. Their tasks, assumptions, and experimental settings differ.')
b+=a('https://github.com/openai/ppo-ewma','作者代码','Author code')
sec.append(('limits','何时可用，何时需要重新验证','When to use it and when to revalidate',b,'§4 requirements; §§5.3, 6.2; Appendix B auxiliary phase, Appendix D'))
make('batch-size-invariance','PPO-EWMA',('批量大小不变性：拆开 PPO 的两个参照','Batch size-invariance: separate PPO’s two references'),('批量缩小后，怎样保留相近的学习行为？从三个策略的职责，到 EWMA 年龄、步长换算与 Procgen 消融。','How can smaller batches preserve similar learning behavior? Follow three policy roles, EWMA age, step-size scaling, and Procgen ablations.'),'NeurIPS 2022 · arXiv 2110.00641v3 · 2022-09-24',src,sec,'- Adopt arXiv v3 for main text and complete appendices; official NeurIPS 2022 proceedings corroborate title, authors, affiliation and publication year. Formal record: https://papers.neurips.cc/paper_files/paper/2022/hash/6ceb6c2150bbf46fd75528a6cd6be793-Abstract-Conference.html . Initial preprint 2021-10-01. Paper-specific acceptance date unverified.\n- Visually inspected PDF pp. 1, 6–8, 19: byline, Figures 1–4 and Table 5. Table 5 read from appendix p.19; experiment values are not read off plotted curves.\n- Reported gaps 0.052 and 0.019: §5.2. Table 5 copied at Default/256: 0.709 (6.87), 0.224 (4.47), 0.041 (4.80), difference-in-differences and Z-scores.\n- H=8 and β=8/9 use the exact stated center-of-mass choice; Table 4 rounds β to 0.889. Do not use rounded β as if it gave exactly H=8.\n- EWMA is a normalized finite-history parameter average in Appendix A. Lab age is steady-state, not exact startup age.\n- Three-policy demo uses synthetic probabilities and advantage; no state-distribution or arbitrary-off-policy unbiasedness claim.\n- Scaling demo derives 65,536/8,192 from Appendix B; independent small-batch SGD/Adam rules, advantage window, Eπ=1 and PPG auxiliary-phase exception are retained.',[('rollout-correction','Rollout 校正','Rollout correction'),('rollout-correction-math','校正的数学','Correction mathematics'),('trm','TRM','TRM'),('ppo','PPO','PPO')],'batch')
print('Rendered TRM and batch size-invariance')
